/**
 * @name Path traversal in file serving
 * @description Serving files based on user input without proper validation can lead to path traversal attacks
 * @kind path-problem
 * @problem.severity error
 * @id py/aiohttp-path-traversal
 * @tags security
 *        external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs
import semmle.python.Concepts

module PathTraversalConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // User-controlled request data in aiohttp
    exists(DataFlow::AttrRead attr |
      attr.getAttributeName() in ["path", "query_string", "match_info", "query"] and
      source = attr
    )
    or
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("aiohttp").getMember("web").getMember("Request").getMember(["match_info", "query"]).getACall() and
      source = call
    )
  }

  predicate isSink(DataFlow::Node sink) {
    // File path operations
    exists(DataFlow::CallCfgNode call |
      (
        call = API::moduleImport("pathlib").getMember("Path").getACall() or
        call = API::moduleImport("os").getMember("path").getMember("join").getACall() or
        call = API::builtin("open").getACall()
      ) and
      sink = call.getArg(_)
    )
    or
    // FileResponse constructor
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("aiohttp").getMember("web").getMember("FileResponse").getACall() and
      sink = call.getArg(0)
    )
  }
}

module PathTraversalFlow = TaintTracking::Global<PathTraversalConfig>;
import PathTraversalFlow::PathGraph

from PathTraversalFlow::PathNode source, PathTraversalFlow::PathNode sink
where PathTraversalFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Potential path traversal from user input $@.", source.getNode(), "user-controlled data"

/**
 * @name Command injection
 * @description Executing system commands with user-controlled data can lead to arbitrary command execution
 * @kind path-problem
 * @problem.severity error
 * @id py/aiohttp-command-injection
 * @tags security
 *        external/cwe/cwe-078
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts

module CommandInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(SystemCommandExecution cmd |
      sink = cmd.getCommand()
    )
  }
}

module CommandInjectionFlow = TaintTracking::Global<CommandInjectionConfig>;
import CommandInjectionFlow::PathGraph

from CommandInjectionFlow::PathNode source, CommandInjectionFlow::PathNode sink
where CommandInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Command injection from $@.", source.getNode(), "user input"

/**
 * @name Open redirect
 * @description HTTP redirects to user-controlled locations can allow phishing attacks
 * @kind path-problem
 * @problem.severity warning
 * @id py/aiohttp-open-redirect
 * @tags security
 *        external/cwe/cwe-601
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module OpenRedirectConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      // HTTPFound, HTTPSeeOther, HTTPTemporaryRedirect, HTTPPermanentRedirect
      call = API::moduleImport("aiohttp").getMember("web").getMember([
        "HTTPFound", "HTTPSeeOther", "HTTPTemporaryRedirect", 
        "HTTPPermanentRedirect", "HTTPMovedPermanently"
      ]).getACall() and
      sink = call.getArg(0)
      or
      sink = call.getArgByName("location")
    )
  }
}

module OpenRedirectFlow = TaintTracking::Global<OpenRedirectConfig>;
import OpenRedirectFlow::PathGraph

from OpenRedirectFlow::PathNode source, OpenRedirectFlow::PathNode sink
where OpenRedirectFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Open redirect from $@.", source.getNode(), "user input"

/**
 * @name SQL injection
 * @description Using user-controlled data in SQL queries can lead to SQL injection
 * @kind path-problem
 * @problem.severity error
 * @id py/aiohttp-sql-injection
 * @tags security
 *        external/cwe/cwe-089
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts

module SqlInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(SqlExecution sql |
      sink = sql.getSql()
    )
  }
}

module SqlInjectionFlow = TaintTracking::Global<SqlInjectionConfig>;
import SqlInjectionFlow::PathGraph

from SqlInjectionFlow::PathNode source, SqlInjectionFlow::PathNode sink
where SqlInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "SQL injection from $@.", source.getNode(), "user input"
